mapper.select:
SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_publish_record
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND publish_status = 1
  AND publish_type = #{publishType}

SELECT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", (SELECT b.output_json FROM bt_publish_step b WHERE b.publish_id = a.id AND b.step_type = '40') AS fileInfo FROM bt_publish_record a WHERE status_cd = '00A'
AND publish_type = #{query.publishType}
AND tenant_id = #{query.tenantId}
ORDER BY updated_time DESC

SELECT , a.obj_id AS "copyTenantId", b.tenant_name AS "copyTenantName", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName" FROM bt_publish_record a LEFT JOIN bt_tenant b ON a.obj_id = b.tenant_id WHERE a.status_cd = '00A' AND a.publish_type = 'copy'
AND a.tenant_id = #{query.tenantId}
AND a.creator_id = #{query.userId}
AND b.tenant_name LIKE
#{query.searchContent}
ORDER BY a.updated_time DESC

SELECT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", b.id AS "modelId", b.model_name AS "modelName", b.model_icon AS "modelIcon", b.use_type FROM bt_publish_record a LEFT JOIN bt_model_finetune b ON a.obj_id = b.id WHERE a.status_cd = '00A'
AND a.publish_type = #{query.publishType}
AND a.tenant_id = #{query.tenantId}
ORDER BY a.updated_time DESC

SELECT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", b.id AS "evalId", c.model_name AS "modelName", c.use_type, b.status, b.accuracy FROM bt_publish_record a LEFT JOIN bt_model_eval b ON a.obj_id = b.id LEFT JOIN bt_model_finetune c ON b.model_id = c.id WHERE a.status_cd = '00A' AND b.status_cd = '00A'
AND a.publish_type = #{query.publishType}
AND a.tenant_id = #{query.tenantId}
AND a.publish_status = #{query.publishStatus}
AND c.model_name LIKE
#{query.searchContent}
ORDER BY a.updated_time DESC
